import React from 'react';

interface MessageIconProps {
  size?: number;
  className?: string;
}

const MessageIcon: React.FC<MessageIconProps> = ({ size = 26, className = '' }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 100 100"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    style={{ overflow: 'visible', filter: 'drop-shadow(0px 3px 5px rgba(0,0,0,0.1))' }}
  >
    {/* Left Wing */}
    <path d="M40 45 Q15 20 5 35 Q20 55 35 55 Z" fill="#38BDF8" />
    <path d="M38 52 Q18 35 5 45 Q20 62 33 60 Z" fill="#0EA5E9" />

    {/* Right Wing */}
    <path d="M60 45 Q85 20 95 35 Q80 55 65 55 Z" fill="#38BDF8" />
    <path d="M62 52 Q82 35 95 45 Q80 62 67 60 Z" fill="#0EA5E9" />

    {/* Letter Body Back */}
    <rect x="25" y="40" width="50" height="36" rx="4" fill="#E2E8F0" />

    {/* Open Flap (Back) */}
    <path d="M25 40 L50 22 L75 40 Z" fill="#CBD5E1" />

    {/* Letter Paper (Sticking out) */}
    <rect x="33" y="28" width="34" height="20" rx="2" fill="#FFFFFF" />
    <line x1="40" y1="36" x2="60" y2="36" stroke="#94A3B8" strokeWidth="2" strokeLinecap="round" />
    <line x1="40" y1="42" x2="50" y2="42" stroke="#94A3B8" strokeWidth="2" strokeLinecap="round" />

    {/* Letter Body Front */}
    <path d="M25 76 L25 40 L50 58 L75 40 L75 76 C75 78.2 73.2 80 71 80 L29 80 C26.8 80 25 78.2 25 76 Z" fill="#F8FAFC" />

    {/* Bottom Flap Lines */}
    <path d="M25 76 L50 58 L75 76" stroke="#E2E8F0" strokeWidth="1.5" strokeLinejoin="round" />

    {/* Cute little eyes */}
    <circle cx="40" cy="62" r="3.5" fill="#1E293B" />
    <circle cx="60" cy="62" r="3.5" fill="#1E293B" />

    {/* Eye glints */}
    <circle cx="39" cy="61" r="1.2" fill="#FFFFFF" />
    <circle cx="59" cy="61" r="1.2" fill="#FFFFFF" />

    {/* Blush */}
    <ellipse cx="33" cy="65" rx="3.5" ry="2" fill="#F472B6" opacity="0.7"/>
    <ellipse cx="67" cy="65" rx="3.5" ry="2" fill="#F472B6" opacity="0.7"/>

    {/* Cute little mouth */}
    <path d="M47 64 Q50 67.5 53 64" stroke="#1E293B" strokeWidth="2" strokeLinecap="round" fill="none"/>
  </svg>
);

export default MessageIcon;
